import os
import unicodedata
import hashlib
import hmac
import secrets
import re
from pathlib import PurePosixPath
from typing import Optional, Tuple

# Secure file serving module with access control

SECRET_KEY = secrets.token_bytes(32)
BASE_DIR = "/var/www/static"
ALLOWED_EXTENSIONS = {".txt", ".html", ".css", ".js", ".png", ".jpg"}


def generate_access_token(username: str, path: str) -> str:
    """Generate HMAC token for authorized file access."""
    msg = f"{username}:{path}".encode("utf-8")
    return hmac.new(SECRET_KEY, msg, hashlib.sha256).hexdigest()


def verify_access_token(username: str, path: str, token: str) -> bool:
    """Constant-time token verification."""
    expected = generate_access_token(username, path)
    return hmac.compare_digest(expected, token)


def _check_path_component(component: str) -> bool:
    """Reject obviously dangerous path components."""
    if component in (".", "..", ""):
        return False
    if "\x00" in component:
        return False
    if component.startswith("."):
        return False
    return True


def _has_valid_extension(filename: str) -> bool:
    """Check file extension against allowlist."""
    _, ext = os.path.splitext(filename)
    return ext.lower() in ALLOWED_EXTENSIONS


def sanitize_path(user_path: str) -> Optional[str]:
    """Sanitize user-provided path to prevent directory traversal.

    Security measures:
    1. Apply Unicode normalization FIRST (before any checks)
    2. Reject null bytes
    3. Reject path components that are . or ..
    4. Reject hidden files (starting with .)
    5. Normalize path separators
    6. Resolve to real path and verify within BASE_DIR
    7. Check file extension allowlist
    """
    # Step 1: Apply Unicode normalization FIRST before any security checks
    # This prevents bypasses where equivalent Unicode representations
    # could evade pattern matching
    user_path = unicodedata.normalize("NFC", user_path)

    # Step 2: Reject null bytes early
    if "\x00" in user_path:
        return None

    # Step 3: Normalize path separators (handle Windows-style)
    cleaned = user_path.replace("\\", "/")

    # Step 4: Remove any URL encoding that might remain
    cleaned = cleaned.replace("%2e", ".").replace("%2E", ".")
    cleaned = cleaned.replace("%2f", "/").replace("%2F", "/")

    # Step 5: Split and validate each component
    parts = cleaned.split("/")
    validated_parts = []
    for part in parts:
        if part == "":
            continue
        if not _check_path_component(part):
            return None
        validated_parts.append(part)

    if not validated_parts:
        return None

    # Step 6: Reconstruct and verify extension
    reconstructed = "/".join(validated_parts)
    if not _has_valid_extension(reconstructed):
        return None

    # Step 7: Build full path
    full_path = os.path.join(BASE_DIR, reconstructed)

    # Step 8: Resolve to real path and verify still within BASE_DIR
    # Use os.path.realpath to resolve symlinks AND normalize
    resolved = os.path.realpath(full_path)

    if not resolved.startswith(os.path.realpath(BASE_DIR) + os.sep) and resolved != os.path.realpath(BASE_DIR):
        return None

    return resolved


def serve_file(username: str, user_path: str, token: str) -> Tuple[int, bytes]:
    """Serve a file if the user has valid access.

    Returns (status_code, content) tuple.
    """
    # Verify authentication token
    if not verify_access_token(username, user_path, token):
        return (403, b"Access denied")

    # Sanitize the requested path
    safe_path = sanitize_path(user_path)
    if safe_path is None:
        return (400, b"Invalid path")

    # Serve the file
    try:
        with open(safe_path, "rb") as f:
            return (200, f.read())
    except FileNotFoundError:
        return (404, b"Not found")
    except PermissionError:
        return (403, b"Permission denied")


def list_directory(username: str, user_path: str, token: str) -> Tuple[int, list]:
    """List files in a directory if user has access."""
    if not verify_access_token(username, user_path, token):
        return (403, [])

    safe_path = sanitize_path(user_path)
    if safe_path is None:
        return (400, [])

    try:
        entries = os.listdir(safe_path)
        # Filter to only show allowed file types
        return (200, [e for e in entries if _has_valid_extension(e)])
    except (FileNotFoundError, NotADirectoryError):
        return (404, [])
